'use client'

import { useEffect, useState } from 'react'
import { useRouter } from 'next/navigation'
import { Scan, LogOut, Package, CheckCircle } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select'
import { useAuth } from '@/contexts/AuthContext'
import { Html5QrcodeScanner } from 'html5-qrcode'
import { useToast } from '@/hooks/use-toast'

interface Resource {
  _id: string
  name: string
  totalQuantity: number
  distributedQuantity: number
  type: string
}

export default function VolunteerDashboard() {
  const { user, logout, loading } = useAuth()
  const router = useRouter()
  const { toast } = useToast()
  const [resources, setResources] = useState<Resource[]>([])
  const [selectedResource, setSelectedResource] = useState('')
  const [scannerActive, setScannerActive] = useState(false)
  const [recentScans, setRecentScans] = useState<any[]>([])

  useEffect(() => {
    if (!loading && (!user || (user.role !== 'volunteer' && user.role !== 'admin'))) {
      router.push('/login')
    }
  }, [user, loading, router])

  useEffect(() => {
    fetchResources()
  }, [])

  useEffect(() => {
    if (scannerActive) {
      const scanner = new Html5QrcodeScanner(
        'qr-reader',
        { fps: 10, qrbox: 250 },
        false
      )

      scanner.render(onScanSuccess, onScanError)

      return () => {
        scanner.clear()
      }
    }
  }, [scannerActive])

  const fetchResources = async () => {
    try {
      const res = await fetch('/api/resources')
      const data = await res.json()
      setResources(data.resources)
    } catch (error) {
      console.error('Failed to fetch resources:', error)
    }
  }

  const onScanSuccess = async (decodedText: string) => {
    if (!selectedResource) {
      toast({
        title: 'Error',
        description: 'Please select a resource first',
        variant: 'destructive',
      })
      return
    }

    setScannerActive(false)

    try {
      const res = await fetch('/api/scan', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          qr_code: decodedText,
          resource_id: selectedResource,
        }),
      })

      const data = await res.json()

      if (res.ok) {
        toast({
          title: 'Success',
          description: 'Resource claimed successfully',
        })
        setRecentScans((prev) => [data.transaction, ...prev.slice(0, 4)])
        fetchResources() // Refresh resource counts
      } else {
        toast({
          title: 'Error',
          description: data.message,
          variant: 'destructive',
        })
      }
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to process scan',
        variant: 'destructive',
      })
    }
  }

  const onScanError = (error: any) => {
    // Ignore scan errors (happens frequently)
  }

  if (loading || !user) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <p>Loading...</p>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-background p-6">
      <div className="max-w-7xl mx-auto space-y-6">
        {/* Header */}
        <div className="flex justify-between items-center">
          <div>
            <h1 className="text-3xl font-bold">Volunteer Dashboard</h1>
            <p className="text-muted-foreground">Welcome, {user.name}</p>
          </div>
          <Button onClick={logout} variant="outline">
            <LogOut className="mr-2 h-4 w-4" />
            Logout
          </Button>
        </div>

        {/* Scanner Card */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center">
              <Scan className="mr-2 h-5 w-5" />
              QR Code Scanner
            </CardTitle>
            <CardDescription>
              Scan participant QR codes to distribute resources
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="space-y-2">
              <label className="text-sm font-medium">Select Resource</label>
              <Select value={selectedResource} onValueChange={setSelectedResource}>
                <SelectTrigger>
                  <SelectValue placeholder="Choose a resource" />
                </SelectTrigger>
                <SelectContent>
                  {resources.map((resource) => (
                    <SelectItem key={resource._id} value={resource._id}>
                      {resource.name} ({resource.distributedQuantity}/{resource.totalQuantity})
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            {!scannerActive ? (
              <Button
                onClick={() => setScannerActive(true)}
                disabled={!selectedResource}
                className="w-full"
              >
                <Scan className="mr-2 h-4 w-4" />
                Start Scanning
              </Button>
            ) : (
              <>
                <div id="qr-reader" className="w-full"></div>
                <Button
                  onClick={() => setScannerActive(false)}
                  variant="outline"
                  className="w-full"
                >
                  Stop Scanning
                </Button>
              </>
            )}
          </CardContent>
        </Card>

        {/* Resources Overview */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center">
              <Package className="mr-2 h-5 w-5" />
              Resources
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {resources.map((resource) => (
                <div key={resource._id} className="p-4 bg-secondary/50 rounded-lg">
                  <h3 className="font-medium">{resource.name}</h3>
                  <p className="text-sm text-muted-foreground">{resource.type}</p>
                  <div className="mt-2">
                    <div className="flex justify-between text-sm">
                      <span>Distributed</span>
                      <span>{resource.distributedQuantity}/{resource.totalQuantity}</span>
                    </div>
                    <div className="w-full bg-secondary rounded-full h-2 mt-1">
                      <div
                        className="bg-primary h-2 rounded-full"
                        style={{
                          width: `${(resource.distributedQuantity / resource.totalQuantity) * 100}%`,
                        }}
                      />
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>

        {/* Recent Scans */}
        {recentScans.length > 0 && (
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center">
                <CheckCircle className="mr-2 h-5 w-5" />
                Recent Scans
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="space-y-2">
                {recentScans.map((scan, index) => (
                  <div key={index} className="flex justify-between items-center p-3 bg-secondary/50 rounded-lg">
                    <div>
                      <p className="text-sm font-medium">Scan #{recentScans.length - index}</p>
                      <p className="text-xs text-muted-foreground">
                        {new Date(scan.timestamp).toLocaleTimeString()}
                      </p>
                    </div>
                    <span className="text-xs bg-green-500/10 text-green-500 px-2 py-1 rounded">
                      {scan.action}
                    </span>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>
        )}
      </div>
    </div>
  )
}
